INSERT INTO `programmes` (`id`, `title`, `slug`, `summary`, `body`, `cover_image`, `partner_name`, `gallery_album_id`, `is_featured`, `is_active`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`, `gallery_photos`) VALUES
(1, 'Digital Infrastructure & Literacy in Ijero-Ekiti', 'ijero-digital-literacy', 'Free literacy interventions, digital skills training for 30 teachers and over 500 students, and a well-equipped computer laboratory and resourceful library at Dzuels Foundation in Ijero-Ekiti.', 'The Digital Infrastructure and Literacy project in Ijero-Ekiti is Dzuels Educational Foundation\'s flagship community technology intervention. Operated in close technical collaboration with the Information Technology Seed Development Initiative (SeedDev), this project addresses the stark digital divide experienced by youth and educators in rural Ekiti State.\n\nThrough this multi-year initiative, we established a well-equipped computer laboratory and a resourceful library at Dzuels Foundation, providing children with access to practical computer training, coding skills, reading materials, and a supportive learning environment. To date, over 500 students have benefited from these learning opportunities, while 30 teachers have been thoroughly trained in digital pedagogy and computer literacy.\n\nOur trainers deliver structured weekend and holiday bootcamps covering foundational computer operations, typing skills, digital research, visual productivity suites, and basic coding paradigms for both pupils and teachers.\n\nBy empowering educators with digital lesson planning competencies and introducing young learners to modern technology early, this programme directly unlocks future career pathways in software engineering, digital entrepreneurship, and academic excellence.', 'front/images/dzuelsCollage.webp', 'Information Technology Seed Development Initiative (SeedDev)', NULL, 1, 1, 2, 'Digital Infrastructure & Literacy in Ijero-Ekiti | Dzuels Foundation', 'Establishing a well-equipped computer laboratory and library at Dzuels Foundation, upskilling 30 teachers, and training over 500 students in practical coding and digital literacy in Ijero-Ekiti.', '2026-10-11 16:36:13', '2026-10-30 10:41:52', NULL),
(2, 'Ijero Tech Day (ITD)', 'ijero-and-tech-day', 'Our annual flagship technology festival celebrating youth innovation, hands-on digital exhibitions, robotics demos, and keynote mentorship from tech industry leaders.', 'Ijero Tech Day (ITD) is our marquee annual showcase where young beneficiaries from across Ekiti State demonstrate their technological inventions, creative software projects, and digital literacy milestones before parents, community leaders, and visiting industry executives.\r\n\r\nEach edition features high-energy student hackathons, coding exhibitions, digital art showcases, and inspirational keynote panels hosted by software engineers, healthcare leaders, and academic consultants from Nigeria and the diaspora. Outstanding teams and student innovators receive educational scholarships, laptops, and direct mentorship placement to foster their continued growth.\r\n\r\nITD serves as both a celebration of community resilience and a launchpad for the next generation of African technology creators.', 'uploads/media/techday/2026/1793278650_kGkpNgSGS8zX.webp', 'SeedDev & Corporate Tech Allies', NULL, 1, 1, 3, 'Ijero Tech Day (ITD) | Dzuels Educational Foundation', 'Annual flagship technology exposition celebrating youth innovation, coding exhibitions, and creative problem-solving among Ekiti youth.', '2026-10-11 16:36:13', '2026-10-29 16:46:51', NULL),
(3, 'Reading Competition', 'reading-competition', 'A grassroots literacy campaign designed to rekindle a passionate reading culture, vocabulary mastery, and textual comprehension among primary and junior secondary students.', 'Reading is the foundational cornerstone of all intellectual development. The Dzuels Reading Competition is an annual literacy advocacy programme that challenges primary and junior secondary pupils across underserved schools to dive deep into literature, African folklore, and contemporary educational texts.\n\nParticipating students receive curated book packs and participate in inter-school reading challenges that assess comprehension, phonetic pronunciation, textual summary, and expressive articulation. In tandem with the competition, our volunteer educators facilitate mobile reading clinics and donate class libraries to partnering schools to sustain reading habits throughout the academic calendar.\n\nBy transforming reading into an exciting, rewarded sport, we build lifelong learners who lead with intellect and curiosity.', 'front/images/about_1.webp', 'ASCEND Education Foundation', NULL, 0, 1, 4, 'Annual Reading Competition | Dzuels Educational Foundation', 'State-wide literacy intervention revitalizing reading culture and comprehension excellence among primary school pupils in Ekiti State.', '2026-10-11 16:36:13', '2026-10-13 14:07:52', NULL),
(4, 'Spelling Bee Contests', 'spelling-bee-contests', 'A high-impact inter-school spelling championship enhancing linguistic confidence, memory retention, public poise, and academic camaraderie for young pupils.', 'The Dzuels Spelling Bee Contest brings together hundreds of eager pupils from diverse public and community schools to test their mastery of the English lexicon in a supportive, spirited tournament.\n\nBeyond teaching orthography and etymology, the Spelling Bee builds crucial non-cognitive skills: composure under pressure, mental agility, sportsmanship, and fearless public speaking. Finalists compete on stage before cheering peers, families, and education inspectors, competing for coveted school fee grants, complete textbook suites, and gold medals.\n\nThis initiative proves that with structured practice and compassionate encouragement, every child can achieve extraordinary linguistic and academic heights.', 'front/images/gallery/optimized/spelling-01.webp', NULL, NULL, 0, 1, 5, 'Spelling Bee Contests | Dzuels Educational Foundation', 'Inter-school competition promoting vocabulary acquisition, public speaking poise, and cognitive development for young learners.', '2026-10-11 16:36:13', '2026-10-13 14:07:52', NULL),
(5, 'Famoyinka Memorial Children\'s Library', 'famoyinka-memorial-library', 'A community-centered children\'s reading sanctuary and creative learning hub in Ijero-Ekiti providing free book lending, weekend study circles, creative arts and crafts, transformational leadership games, and educational excursions.', 'The Famoyinka Memorial Children\'s Library is Dzuels Educational Foundation\'s dedicated literacy and youth enrichment sanctuary in Ijero-Ekiti. Established in loving memory of a lifelong community champion for child welfare and learning, the library provides a safe, welcoming, and vibrant environment where young learners from indigent backgrounds can discover the joy of books, cultivate imaginative thinking, and build foundational leadership qualities.\n\nOur extensive collection spans African literature, classic folklore, beginner phonics, science and mathematics workbooks, reference encyclopedias, and engaging fiction. Beyond daily book loans, the library hosts structured weekend reading circles, interactive storytelling sessions, creative arts and crafts workshops, and transformational leadership board challenges that instill discipline, teamwork, and fearless curiosity.\n\nIn addition, our library beneficiaries participate in fully sponsored educational excursions — such as nature and environmental science discovery field trips to Ikogosi Warm Springs — expanding their horizons beyond classroom walls. Every service, book loan, and mentorship activity is offered completely free of charge to all children in Ijero-Ekiti and surrounding communities.', 'front/images/gallery/optimized/famoyinka-01.webp', 'Famoyinka Family & Community Literacy Patrons', NULL, 1, 1, 1, 'Famoyinka Memorial Children\'s Library | Dzuels Educational Foundation', 'Community children\'s library providing free book borrowing, creative crafts, leadership games, and literacy circles in Ijero-Ekiti.', '2026-10-13 14:07:52', '2026-10-13 14:07:52', NULL),
(6, 'Transformational leadership (TRANSCOMM)', 'transformational-leadership-transcomm', 'A values-driven mentorship and character development initiative empowering emerging youth leaders with ethical mindset, public speaking, critical thinking, and community impact.', 'Transformational leadership (TRANSCOMM) is Dzuels Educational Foundation\'s flagship youth leadership and character development initiative. Rooted in our core DRNICER principles—Discipline, Responsibility, No-Excuse, Integrity, Compassion, Excellence, and Respect—TRANSCOMM prepares young Nigerians to lead with purpose, moral conviction, and actionable vision in their schools and communities.\n\nThrough interactive leadership circles, public speaking workshops, ethical decision-making case studies, and community impact projects, participants learn to move beyond passive observation and become proactive problem-solvers. The curriculum integrates emotional intelligence, teamwork exercises, civic responsibility, and visionary goal-setting, inspiring youth to transform adversity into leadership capability.\n\nTRANSCOMM beneficiaries actively spearhead peer mentorship groups, organize community cleanups, and champion literacy and digital skills advocacy among their peers, embodying true transformative leadership from the grassroots up.', 'front/images/about_1.webp', 'Priscilla\'s Upper Room & Leadership Mentors', NULL, 1, 1, 6, 'Transformational Leadership (TRANSCOMM) | Dzuels Educational Foundation', 'Values-driven mentorship, ethical leadership training, and mindset transformation for emerging community youth leaders in Ekiti State.', '2026-10-30 10:41:52', '2026-10-30 10:41:52', NULL),
(7, 'Ijero Tech Day (ITD)', 'innovation-and-tech-day', 'Our annual flagship technology festival celebrating youth innovation, hands-on digital exhibitions, robotics demos, and keynote mentorship from tech industry leaders.', 'Ijero Tech Day (ITD) is our marquee annual showcase where young beneficiaries from across Ekiti State demonstrate their technological inventions, creative software projects, and digital literacy milestones before parents, community leaders, and visiting industry executives.\n\nEach edition features high-energy student hackathons, coding exhibitions, digital art showcases, and inspirational keynote panels hosted by software engineers, healthcare leaders, and academic consultants from Nigeria and the diaspora. Outstanding teams and student innovators receive educational scholarships, laptops, and direct mentorship placement to foster their continued growth.\n\nITD serves as both a celebration of community resilience and a launchpad for the next generation of African technology creators.', 'front/images/gallery/optimized/itd-2025-05.webp', 'SeedDev & Corporate Tech Allies', NULL, 1, 1, 3, 'Ijero Tech Day (ITD) | Dzuels Educational Foundation', 'Annual flagship technology exposition celebrating youth innovation, coding exhibitions, and creative problem-solving among Ekiti youth.', '2026-10-30 10:41:52', '2026-10-30 10:41:52', NULL);
INSERT INTO `events` (`id`, `title`, `slug`, `summary`, `description`, `event_date`, `end_date`, `venue`, `theme`, `objective`, `banner_image`, `schedule`, `is_registration_open`, `is_active`, `sort_order`, `seo_title`, `seo_description`, `created_at`, `updated_at`, `gallery_album_id`, `gallery_photos`) VALUES
(1, 'Ijero Tech-Day 2026 (ITD 2026)', 'ijero-tech-day-2026', 'Empowering 300 children with practical AI tools across 10 rotating batches of 30, inside interactive labs and garden booths, plus 22 cohort graduate certificates.', 'Ijero Tech-Day 2026 (ITD 2026) is the flagship community technology festival organized by Dzuels Educational Foundation under the theme "Learning Today, Creating Tomorrow". Held at the AAoJ Memorial Learning Center in Ijero-Ekiti, this high-impact gathering brings together 300 selected primary and secondary school students, dedicated educators, and community mentors for a transformative full-day digital literacy and AI immersion experience.\r\n\r\nStudents participate in synchronized 10-batch rotations of 30 participants each across two experiential learning zones:\r\n1. Inside Practical Lab: 20-minute intensive hands-on sessions introducing practical Artificial Intelligence tools, prompt thinking, and digital creativity on modern computing equipment.\r\n2. Garden Innovation Pavilion: Outdoor creative stations featuring an AI Image Creation Booth, interactive Tech Quizzes, student digital logic challenges, and prize giveaways.\r\n\r\nThe event also features the milestone Cohort 2026 Certificate Presentations, honoring 22 outstanding students who completed our rigorous digital literacy training, alongside community educational keynotes and educator recognition.', '2026-10-17 08:00:00', '2026-10-17 17:00:00', 'AAoJ Memorial Learning Center, Ijero-Ekiti (inside + garden)', 'Learning Today, Creating Tomorrow', 'Empowering children with AI tools to learn smarter, think creatively, and build the future.', 'front/images/events/itd-2026-backdrop.webp', '[{"time":"08:00 AM - 09:00 AM","title":"Accreditation, Batch Allocation & Welcome Assembly","speaker":"Dzuels Foundation Coordination Team"},{"time":"09:00 AM - 09:30 AM","title":"Opening Ceremony: \\"Learning Today, Creating Tomorrow\\"","speaker":"Board of Trustees & Community Leaders"},{"time":"09:30 AM - 01:00 PM","title":"Morning AI Lab & Garden Rotation Sessions (Batches 1 \\u2013 5)","speaker":"Tech Instructors & Mentors"},{"time":"01:00 PM - 02:00 PM","title":"Lunch Break, Networking & Image Creation Showcase","speaker":"Students & Guest Exhibitors"},{"time":"02:00 PM - 04:30 PM","title":"Afternoon AI Lab & Garden Rotation Sessions (Batches 6 \\u2013 10)","speaker":"Tech Instructors & Mentors"},{"time":"04:30 PM - 05:00 PM","title":"Cohort Graduation: Presentation of 22 Certificates & Grand Finale","speaker":"Foundation Leadership & Dignitaries"}]', 0, 1, 1, 'Ijero Tech-Day 2026 (ITD 2026) | Dzuels Educational Foundation', 'Join 300 students and educators for Ijero Tech-Day 2026 on Saturday, October 3, 2026. Theme: Learning Today, Creating Tomorrow. Objective: Empowering children with AI tools to learn smarter, think creatively, and build the future.', '2026-10-11 16:36:13', '2026-10-29 14:57:12', NULL, NULL),
(2, 'Ijero Tech Day 2024 (Inaugural Edition)', 'ijero-tech-day-2024', 'The inaugural gathering that connected over 150 local students to digital literacy tools, robotics kits, and mentorship.', 'The 2024 edition of Ijero Tech Day set a new benchmark for grassroots technology engagement in Ekiti State. Facilitated in collaboration with Information Technology Seed Development Initiative (SeedDev), the gathering welcomed 150+ students from 15 secondary schools across Ijero-Ekiti for practical digital workshops and competitions.\n\nHighlights included interactive coding basics, typing mastery awards, and the official handover of modern computing equipment to participating schools.', '2024-11-15 09:00:00', '2024-11-15 15:00:00', 'Ijero-Ekiti Civic Centre, Ekiti State', 'Igniting Digital Potential in Ijero-Ekiti', 'Introducing foundational digital literacy, typing mastery, and computer hardware to rural secondary school students.', 'uploads/media/gallery/1793276523_aYUykvBKB4CR.webp', '[{"time":"09:00 AM - 10:00 AM","title":"Opening Ceremony & Keynote Address","speaker":"Dzuels Team & Education Officials"},{"time":"10:00 AM - 12:30 PM","title":"Digital Literacy Workshops & Coding Clinic","speaker":"SeedDev Instructors"},{"time":"01:00 PM - 02:30 PM","title":"Student Competitions & Award Presentations","speaker":"Guest Evaluators"}]', 0, 1, 3, 'Ijero Tech Day 2024 | Dzuels Educational Foundation', 'Highlights and outcomes from the inaugural Ijero Tech Day 2024 in Ekiti State.', '2026-10-11 16:36:13', '2026-10-29 13:02:48', NULL, NULL),
(3, 'Ijero Tech Day 2025 (2nd Annual Edition)', 'ijero-tech-day-2025', 'The second annual flagship gathering celebrating student digital innovation, robotics demos, and creative problem solving across Ijero-Ekiti.', 'Ijero Tech Day 2025 brought together over 220 students, teachers, and technology mentors from across Ekiti State for an intensive full-day celebration of innovation and practical STEM skills. Following the success of the 2024 inaugural gathering, the 2025 edition featured expanded coding hackathons, beginner robotics exhibitions, visual design clinics, and keynote addresses by tech professionals.\n\nStudents demonstrated innovative community problem-solving projects, and participating schools received refurbished desktop computers, books, and scholarship recognition for outstanding student innovators.', '2025-10-25 09:00:00', '2025-10-25 16:30:00', 'AAoJ Memorial Learning Center & Ijero Civic Hall, Ijero-Ekiti', 'Empowering Rural Youth Through Innovation & Technology', 'Accelerating digital literacy, robotics awareness, and creative technology problem-solving among rural students.', 'uploads/media/techday/2025/1793278500_XUSj1fYPJy42.webp', '[{"time":"09:00 AM - 10:00 AM","title":"Opening Assembly & Keynote: Innovation in Rural Education","speaker":"Foundation Leadership & Guests"},{"time":"10:00 AM - 01:00 PM","title":"Interactive Coding, Robotics & Digital Media Workshops","speaker":"Tech Mentors & Facilitators"},{"time":"01:00 PM - 02:00 PM","title":"Lunch Break & Student Innovation Exhibition","speaker":"Student Innovators"},{"time":"02:00 PM - 04:00 PM","title":"Youth Hackathon Demos & Pitch Presentations","speaker":"Student Teams & Judges"},{"time":"04:00 PM - 04:30 PM","title":"Awards, School Equipment Presentation & Closing","speaker":"Dignitaries"}]', 0, 1, 2, 'Ijero Tech Day 2025 | Dzuels Educational Foundation', 'Highlights and student exhibitions from the 2nd annual Ijero Tech Day held on October 25, 2025 in Ijero-Ekiti.', '2026-10-29 13:02:48', '2026-10-29 13:02:48', NULL, NULL);
