INSERT INTO `page_sections` (`id`, `page_key`, `section_key`, `headline`, `subheadline`, `body_text`, `image_path`, `button_text`, `button_url`, `meta_data`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'home', 'hero', 'Addressing poverty through quality education and skills acquisition', 'Dzuels Educational Foundation', 'Empowering indigent Nigerian children, youth, and educators with free digital literacy, school support, leadership mentoring, and community welfare.', 'front/images/home_1.webp', 'Donate Now', '/donate', NULL, 10, 1, '2026-10-11 16:36:13', '2026-10-29 20:07:48'),
(2, 'home', 'who_we_are', 'Dedicated to Transforming Lives and Communities Through Education', 'Who We Are', 'Dzuels Educational Foundation is a non-profit organisation dedicated to addressing poverty by providing quality education and skills acquisition for indigent children and youth across Nigeria. Founded in 2015, we bridge educational inequality by equipping underserved communities with modern digital skills, literacy support, and vital infrastructure.\n\nOur initiatives ensure that children from low-income backgrounds have the tools, guidance, and environments required to thrive in a rapidly changing world.', 'front/images/about_1.webp', 'Learn More About Us', '/about', NULL, 20, 1, '2026-10-11 16:36:13', '2026-10-29 20:07:48'),
(3, 'home', 'vision_mission', 'Our Core Purpose & Guiding Principles', 'Vision & Mission', 'Vision: An equitable society where every child, irrespective of socio-economic background, has access to quality education, modern digital literacy, and the opportunity to achieve their highest human potential.\n\nMission: To dismantle educational barriers for indigent youth in Nigeria by deploying digital classrooms, scholarship support, literacy outreach, and mentorship that spark lifelong empowerment.', NULL, NULL, NULL, NULL, 30, 1, '2026-10-11 16:36:13', '2026-10-29 20:07:48'),
(4, 'home', 'values', 'Our DRNICER Core Values', 'Guiding Principles', 'Dynamism, Resilience, Novelty, Integrity, Compassion, Excellence, Responsibility — these principles define every classroom we build and partnership we form.', NULL, NULL, NULL, NULL, 40, 1, '2026-10-11 16:36:13', '2026-10-29 20:07:48'),
(5, 'home', 'causes', 'Programs that Bridge the Opportunity Divide', 'Our 6 Impact Causes', 'From digital hubs in Ijero-Ekiti to annual literacy contest, and much more in between, our causes are designed to uplift communities from the ground up.', 'front/images/cause.webp', NULL, NULL, '{"tagline":"AN INTEGRATED APPROACH TO THE TOTAL WELL BEING OF THE CHILD","pillars":[{"title":"Education Support","ministry":"Paul\'s academy","description":"Paying school fees, supplying curriculum textbooks, notebooks, uniforms, and educational kits to keep children in classrooms.","icon":"\\ud83c\\udf93"},{"title":"Skills Acquisition","ministry":"Peter\'s net","description":"Hands-on digital literacy, computer coding, and practical vocational training equipping youth with 21st-century self-reliance.","icon":"\\ud83d\\udcbb"},{"title":"Advocacy","ministry":"Deborah congress","description":"Championing child protection, education policy awareness, equal opportunity for indigent girls, and youth rights.","icon":"\\ud83d\\udce2"},{"title":"Feeding families","ministry":"Naomi\'s kitchen","description":"Targeted nutritional relief, food assistance, and hunger alleviation ensuring indigent pupils have the energy to learn.","icon":"\\ud83c\\udf72"},{"title":"Transformative leadership Training","ministry":"Priscilla\'s upper room","description":"Values-driven mentorship, ethical leadership training, and mindset transformation for emerging community leaders.","icon":"\\ud83c\\udf1f"},{"title":"Health awareness and support","ministry":"Luke\'s Tent","description":"Health education, medical screenings, personal hygiene kits, and basic medical support for vulnerable children and families.","icon":"\\ud83e\\ude7a"}]}', 50, 1, '2026-10-11 16:36:13', '2026-10-30 10:41:53'),
(6, 'home', 'featured_project', 'Ijero-Ekiti Digital Infrastructure and Literacy Initiative', 'Flagship Project', 'Establishing a well-equipped computer laboratory and a resourceful library at Dzuels Foundation, providing children with access to practical computer training, coding skills, reading materials, and a supportive learning environment. To date, over 500 students have benefited from these learning opportunities.', 'front/images/dzuelsCollage.webp', 'Explore Our Programmes', '/programmes', NULL, 70, 1, '2026-10-11 16:36:13', '2026-10-30 10:41:53'),
(7, 'home', 'cta', 'Join Us in Shaping the Future of Nigeria\'s Youth', 'Take Action Today', 'Whether through individual, family or corporate sponsorship, volunteer mentorship, financial donations or legacy giving, your partnership empowers the next generation.', NULL, 'Get Involved Today', '/get-involved', NULL, 80, 1, '2026-10-11 16:36:13', '2026-10-30 10:41:53'),
(8, 'about', 'hero', 'Transforming Lives [italic]Page[/italic] by [italic]Page[/italic]', 'About Dzuels Educational Foundation', 'A decade of dedicated service alleviating poverty through quality education, youth literacy interventions, and digital empowerment in Nigeria.', 'front/images/gallery/optimized/general-01.webp', 'Support Our Mission', '/donate', NULL, 10, 1, '2026-10-11 16:36:13', '2026-10-30 11:49:19'),
(9, 'about', 'story', 'A Decade of Dedicated Service (Since 2015)', 'Our Heritage & Purpose', 'Dzuels Educational Foundation is a registered non-profit charity founded on 22nd June 2015. Established with an unwavering commitment to child welfare, we exist to provide comprehensive educational support, life skills, and digital literacy for indigent Nigerian children and youth.\n\nOver the last ten years, our programs have operated through our well-equipped computer lab and library facility in Ijero-Ekiti, alongside direct educational interventions across communities in Ekiti State. We believe every child deserves the tools, dignity, and encouragement to pursue knowledge without the burden of unpaid tuition fees or missing textbooks.\n\nA cornerstone of this commitment is the Famoyinka Memorial Children\'s Library in Ijero-Ekiti—a permanent reading sanctuary providing free book loans, weekend study circles, creative arts, and transformational leadership activities for local youth.\n\nRecognizing that learning does not happen in isolation, our work also reaches vulnerable households: providing nutritional assistance to indigent families through widows, creating deep awareness of social vices, and fostering transformational leadership in every classroom we touch.', 'front/images/about_1.webp', NULL, NULL, '{"milestones":[{"value":"10+","label":"Years of Service"},{"value":"750+","label":"Students Trained"},{"value":"30+","label":"Teachers Trained"}],"badge":{"kicker":"Milestone","title":"10+ Years of Direct Community Impact"}}', 30, 1, '2026-10-11 16:36:13', '2026-10-30 11:24:31'),
(10, 'about', 'approach', 'Our Integrated Intervention Approach', 'Total Well-Being of the Child', 'We believe sustainable education requires a whole-child model: combining academic sponsorship, classroom infrastructure, moral mentorship, and household nutritional stability.', NULL, NULL, NULL, '{"pillars":[{"title":"Tuition & School Fees Support","description":"Paying school fees and registration costs directly for indigent students in public and non-profit schools to prevent dropout and keep vulnerable children in class.","icon":"academic-cap"},{"title":"Educational Materials & Uniforms","description":"Providing textbooks, exercise books, writing materials, school bags, and uniforms so that students can attend school with confidence, dignity, and pride.","icon":"book-open"},{"title":"Equipping Digital Labs & Libraries","description":"Setting up digital ICT facilities, supplying desktop computers, and upgrading library resources in community facilities to bridge the digital divide.","icon":"computer-desktop"},{"title":"Mentorship & Leadership Training","description":"Instilling the DRNICER values (Discipline, Responsibility, No-Excuse, Integrity, Compassion, Excellence, Respect) through structured mentorship and leadership camps.","icon":"user-group"},{"title":"Family Nutrition & Widow Welfare","description":"Supporting struggling households and vulnerable widows with food relief packages, micro-support, and welfare assistance so children are nourished and ready to learn.","icon":"heart"},{"title":"Health Services & Social Awareness","description":"Conducting health screenings, promoting hygiene, and raising awareness regarding social vices, substance abuse, and cyber-safety to protect youth development.","icon":"shield-check"}]}', 40, 1, '2026-10-11 16:36:13', '2026-10-30 11:24:31'),
(11, 'about', 'leadership', 'Board of Trustees, Management & Advisory Board', 'Foundation Governance', 'Guided by dedicated educators, technologists, and community leaders committed to absolute transparency, integrity, and social [Badge]stewardship.[Badge]', NULL, NULL, NULL, NULL, 20, 1, '2026-10-11 16:36:13', '2026-10-30 11:24:31'),
(12, 'programmes', 'hero', 'Our Impact Programmes', 'Impact In Action', 'Empowering Nigerian children, teachers, and schools through grassroots literacy campaigns, digital labs, and STEM innovation showcases.', 'front/images/gallery/optimized/itd-2025-05.webp', 'Partner on a Programme', '/get-involved', NULL, 10, 1, '2026-10-11 16:36:13', '2026-10-29 20:07:48'),
(13, 'programmes', 'overview', 'Targeted Initiatives for Lasting Community Impact', 'Empowering Next-Gen Leaders', 'Every programme is designed with measurable outcomes: improving student academic performance, fostering digital confidence, and preparing youth for future careers.', NULL, NULL, NULL, NULL, 2, 1, '2026-10-11 16:36:13', '2026-10-11 16:36:13'),
(14, 'contact', 'hero', 'We Are Always Available to Connect With You', 'Get in Touch', 'Have a question regarding our youth literacy initiatives, school computer labs, or community partnerships? Send us a message or visit our headquarters in Ijero-Ekiti.', 'front/images/gallery/optimized/general-05.webp', NULL, NULL, NULL, 10, 1, '2026-10-11 16:36:13', '2026-10-29 20:07:48'),
(15, 'contact', 'office', 'Visit Our Office', 'Headquarters', 'AAoJ Memorial Learning Center, 12b Doherty Road, Ijero-Ekiti, Ekiti State, Nigeria. Open Monday through Friday, 8:00 AM to 5:00 PM.', NULL, NULL, NULL, NULL, 20, 1, '2026-10-11 16:36:13', '2026-10-29 20:07:48'),
(16, 'donate', 'hero', 'Power Real Futures Through Education', 'Giving & Stewardship', 'Your generosity provides classroom computer labs, essential textbooks, digital literacy, and student empowerment in rural Nigerian schools.', 'front/images/gallery/optimized/reading-01.webp', 'GTBank Direct Transfer', '#bank-transfer', NULL, 10, 1, '2026-10-11 16:36:13', '2026-10-29 20:07:48'),
(17, 'donate', 'where_your_gift_goes', 'Where Your Contribution Goes', 'Financial Accountability', 'We maintain zero-waste budgeting. Here is how donations are allocated across our community programmes and educational initiatives.', NULL, NULL, NULL, NULL, 30, 1, '2026-10-11 16:36:13', '2026-10-29 20:07:48'),
(18, 'get_involved', 'hero', 'Get Involved & Power Youth Potential', 'Make a Difference With Us', 'Whether giving your time as an inspirational mentor or collaborating as an institutional partner, your involvement directly accelerates youth digital literacy and educational equity across Ekiti State.', 'front/images/gallery/optimized/general-02.webp', 'Apply to Volunteer', '#application-form-card', NULL, 10, 1, '2026-10-11 16:36:13', '2026-10-29 20:07:48'),
(19, 'get_involved', 'intro', 'Volunteer or Partner With Dzuels', 'Create Lasting Change', 'Whether you want to mentor young coders during Ijero Tech Day or sponsor a digital laboratory in a public school, there is a place for you in our mission.', NULL, NULL, NULL, NULL, 2, 1, '2026-10-11 16:36:13', '2026-10-11 16:36:13'),
(20, 'contact', 'form', 'Send Us a Message', 'Online Inquiry', 'Fill out the form below and a representative from Dzuels Educational Foundation will get in touch with you promptly.', NULL, NULL, NULL, NULL, 30, 1, '2026-10-13 14:39:14', '2026-10-29 20:07:48'),
(21, 'contact', 'map', 'Headquarters Location', 'Physical Visits Welcomed', 'Our central educational center and community operations are based in Ijero-Ekiti, Ekiti State, Nigeria. Please call in advance so our field coordinators can assist with your schedule.', NULL, NULL, NULL, NULL, 40, 1, '2026-10-13 14:39:14', '2026-10-29 20:07:48'),
(22, 'home', 'famoyinka_library', 'Famoyinka Memorial Children\'s Library', 'Permanent Literacy Sanctuary', 'An active, community-anchored hub dedicated to childhood literacy, creative self-expression, and transformational leadership in Southwest Nigeria.', NULL, 'Explore Library Programme', '/programmes/famoyinka-memorial-library', '{"photos":[{"image":"front\\/images\\/gallery\\/optimized\\/famoyinka-01.webp","label":"Free Book Loans","alt":"Student selecting books at Famoyinka Memorial Children\'s Library"},{"image":"front\\/images\\/gallery\\/optimized\\/famoyinka-03.webp","label":"Creative Arts","alt":"Creative watercolor art workshop"},{"image":"front\\/images\\/gallery\\/optimized\\/famoyinka-02.webp","label":"Leadership Games","alt":"Leadership teamwork games and sports"},{"image":"front\\/images\\/gallery\\/optimized\\/famoyinka-04.webp","label":"Ikogosi Excursion","alt":"Ikogosi Warm Springs educational excursion"}]}', 60, 1, '2026-10-13 18:00:55', '2026-10-29 20:07:48'),
(23, 'about', 'famoyinka_library', 'Famoyinka Memorial Children\'s Library', 'Permanent Community Hub', 'Established as a permanent physical sanctuary in Ijero-Ekiti, the Famoyinka Memorial Children\'s Library brings our 10-year holistic child development vision to life every day. It provides children and families with open access to rich literature, quiet study workstations, and weekend mentorship circles.', 'front/images/gallery/optimized/famoyinka-01.webp', 'Explore Library Programme', '/programmes/famoyinka-memorial-library', '{"bullets":["Free fiction, science & culture book loans","Weekend study circles & digital lab access","Creative arts, crafts & watercolor workshops","Leadership games & Ikogosi nature trips"],"badge":{"location":"Ijero-Ekiti, Nigeria","title":"A Living Sanctuary for Young Readers"}}', 50, 1, '2026-10-29 20:07:48', '2026-10-30 11:24:31'),
(24, 'about', 'trustees', 'Board of Trustees', 'Stewardship & Governance', 'Our governing trustees provide strategic guidance, fiduciary integrity, and long-term vision to uphold our educational mission.', NULL, NULL, NULL, NULL, 60, 1, '2026-10-29 20:07:48', '2026-10-30 11:24:31'),
(25, 'about', 'management', 'Management Team & Project Coordinators', 'Executive Operations', 'Experienced professionals, educators, and field organizers managing day-to-day community operations in Ijero-Ekiti.', NULL, NULL, NULL, NULL, 70, 1, '2026-10-29 20:07:48', '2026-10-30 11:24:31'),
(26, 'about', 'advisors', 'Advisory Board', 'Strategic Guidance', 'Respected sector veterans, academics, and legal consultants advising our governance policies and educational strategy.', NULL, NULL, NULL, NULL, 80, 1, '2026-10-29 20:07:48', '2026-10-30 11:24:31'),
(27, 'about', 'cta', 'Support Our 10-Year Mission of Hope', 'Partner With Us', 'Join us in bringing life-changing education and digital opportunities to children in need across Southwest Nigeria.', NULL, 'Donate Now', '/donate', NULL, 90, 1, '2026-10-29 20:07:48', '2026-10-30 11:24:31'),
(28, 'programmes', 'flagship', 'Ijero Tech Day (ITD)', 'Annual Flagship Festival', 'Our premier annual gathering celebrating student innovation, robotics showcases, youth hackathons, and high-impact tech industry mentorship in Ijero-Ekiti.', NULL, 'Explore Tech Day Flagship', '/events/ijero-tech-day-2026', NULL, 20, 1, '2026-10-29 20:07:48', '2026-10-29 20:07:48'),
(29, 'programmes', 'catalog', 'Continuous Educational Initiatives', 'Intervention Catalog', 'Explore our continuous projects supporting classrooms, libraries, digital hubs, and young scholars.', NULL, NULL, NULL, NULL, 30, 1, '2026-10-29 20:07:48', '2026-10-29 20:07:48'),
(30, 'programmes', 'cta', 'Help Us Expand These Transformative Initiatives', 'Empower a Classroom', 'Your partnership provides desktop computers, school books, scholarship grants, and expert mentorship to children who need it most.', NULL, 'Sponsor an Initiative', '/donate', NULL, 40, 1, '2026-10-29 20:07:48', '2026-10-29 20:07:48'),
(31, 'donate', 'giving_channels', 'Choose How You Want to Give', 'Multiple Giving Pathways', 'Direct bank transfer, U.S. diaspora giving via Givebutter, why donate stewardship guarantee, and in-kind equipment support.', NULL, NULL, NULL, NULL, 20, 1, '2026-10-29 20:07:48', '2026-10-29 20:07:48'),
(32, 'donate', 'faq', 'Frequently Asked Questions', 'Transparency & Giving Information', 'Learn more about our non-profit standing, fund allocation, international tax receipts, and direct updates.', NULL, NULL, NULL, NULL, 40, 1, '2026-10-29 20:07:48', '2026-10-29 20:07:48'),
